""" + SELECTOR_FN + """
  const out = [];
  document.querySelectorAll('body *').forEach(el => {
    const s = getComputedStyle(el);
    if (s.display === 'none' || s.visibility === 'hidden') return;
    if (el.closest('[aria-hidden="true"], [inert], dialog:not([open])')) return;
